def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]
    opp_defects = sum(1 for x in opp_actions if x == 'D')
    my_defects = sum(1 for x in my_actions if x == 'D')

    if n >= 95:
        return 'D'

    if opp_defects == 0:
        if my_defects == 0:
            if n >= 20 and n % 10 == 0:
                return 'D'
            return 'C'
        else:
            if my_defects > 5:
                return 'D'
            if my_actions[-1] == 'D':
                return 'C'
            else:
                return 'D'

    last_my, last_opp = history[-1]

    recent_opp_d = sum(1 for x in opp_actions[-5:] if x == 'D')
    if n >= 85 and recent_opp_d >= 2:
        return 'D'

    if opp_defects >= 4 and opp_defects * 2 >= n:
        return 'D'
    if opp_defects >= 3 and opp_defects * 3 >= n:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        else:
            if any(x == 'D' for x in my_actions[-3:]):
                return 'C'
            if opp_defects == 1 and n < 85:
                return 'C'
            return 'D'

    if last_my == 'D':
        return 'C'

    if recent_opp_d >= 2:
        return 'D'
    if opp_defects >= 2 and opp_defects * 3 >= n:
        return 'D'

    return 'C'
